-- clean.sql — abpf_titolari_piva_regione
-- IRPEF delle persone fisiche titolari di partita IVA (modello ABPF, "Tutte le
-- tipologie"): redditi dichiarati, imposta e IVA per regione.
-- Vista MEF analisi_stat ABPFTIT0201 — "Titolari di partita IVA" — "Regione".
--
-- ⚠️ Lettura PER NOME (`all_varchar: true`, header alla riga 10), non posizionale:
-- l'INSIEME delle colonne cambia tra gli anni (149 nomi nei file 2012-2013, 150
-- nel 2014-2018, 144 dal 2019) e l'ordine non e' stabile (nel 2014-2018 cambia da
-- un anno all'altro; spostamento massimo osservato: 6 posizioni). Si referenziano
-- solo le colonne presenti in TUTTI gli anni coperti (file 2016-2025, a.i.
-- 2015-2024): 144 colonne comuni, di cui 3 chiavi e 47 misure.
-- `all_varchar` serve anche perché i numeri sono in formato italiano: con
-- `source: auto` lo sniffing tipizza DOUBLE le colonne i cui valori hanno un solo
-- punto (es. "121.330") e le macro normalize_italian_* le corromperebbero (×10/÷10).
--
-- `anno` = anno d'imposta (l'URL MEF usa l'anno di presentazione: {year} - 1).
-- Ammontari in migliaia di euro → ×1000. Colonne "Media" scartate.
-- `***` = dato oscurato dalla fonte (privacy) → NULL via TRY_CAST.
-- Righe escluse: header (codice='Codice'), `TOTALE` ('0'), `Non indicata` ('00'),
-- la riga "(*) Comprensivo dei valori nulli" e la nota finale (codice NULL).
--
-- ⚠️ Le colonne NON sono additive: sono grandezze dichiarate su righe diverse del
-- modello (es. `reddito_complessivo` include anche lavoro dipendente e pensioni,
-- e le voci per tipo di reddito si sovrappongono in parte).

WITH raw_parsed AS (
    SELECT
        CAST({year} - 1 AS INTEGER)                              AS anno,
        normalize_string("Regione")                               AS regione,
        LPAD(normalize_string("Codice"), 2, '0')                 AS cod_regione,
        normalize_italian_integer("Numero titolari di partita IVA") AS numero_titolari,
        normalize_italian_integer("Acconti versati - Frequenza")  AS acconti_versati_frequenza,
        normalize_italian_number("Acconti versati - Ammontare")   AS _acconti_versati_eur,
        normalize_italian_integer("Addizionale comunale dovuta - Frequenza")  AS addizionale_comunale_dovuta_frequenza,
        normalize_italian_number("Addizionale comunale dovuta - Ammontare")   AS _addizionale_comunale_dovuta_eur,
        normalize_italian_integer("Addizionale regionale dovuta - Frequenza")  AS addizionale_regionale_dovuta_frequenza,
        normalize_italian_number("Addizionale regionale dovuta - Ammontare")   AS _addizionale_regionale_dovuta_eur,
        normalize_italian_integer("Altri redditi da lavoro autonomo e redditi da recupero start up - Frequenza")  AS altri_redditi_da_lavoro_autonomo_e_redditi_da_recupero_start_up_frequenza,
        normalize_italian_number("Altri redditi da lavoro autonomo e redditi da recupero start up - Ammontare")   AS _altri_redditi_da_lavoro_autonomo_e_redditi_da_recupero_start_up_eur,
        normalize_italian_integer("Eccedenza d'imposta risultante dalla precedente dichiarazione - Frequenza")  AS eccedenza_d_imposta_risultante_dalla_precedente_dichiarazione_frequenza,
        normalize_italian_number("Eccedenza d'imposta risultante dalla precedente dichiarazione - Ammontare")   AS _eccedenza_d_imposta_risultante_dalla_precedente_dichiarazione_eur,
        normalize_italian_integer("Imposta lorda - Frequenza")  AS imposta_lorda_frequenza,
        normalize_italian_number("Imposta lorda - Ammontare")   AS _imposta_lorda_eur,
        normalize_italian_integer("Imposta netta - Frequenza")  AS imposta_netta_frequenza,
        normalize_italian_number("Imposta netta - Ammontare")   AS _imposta_netta_eur,
        normalize_italian_integer("Irpef a credito - Frequenza")  AS irpef_a_credito_frequenza,
        normalize_italian_number("Irpef a credito - Ammontare")   AS _irpef_a_credito_eur,
        normalize_italian_integer("Irpef a debito - Frequenza")  AS irpef_a_debito_frequenza,
        normalize_italian_number("Irpef a debito - Ammontare")   AS _irpef_a_debito_eur,
        normalize_italian_integer("Iva a debito - Frequenza")  AS iva_a_debito_frequenza,
        normalize_italian_number("Iva a debito - Ammontare")   AS _iva_a_debito_eur,
        normalize_italian_integer("Iva detraibile - Frequenza")  AS iva_detraibile_frequenza,
        normalize_italian_number("Iva detraibile - Ammontare")   AS _iva_detraibile_eur,
        normalize_italian_integer("Perdita da lavoro autonomo - Frequenza")  AS perdita_da_lavoro_autonomo_frequenza,
        normalize_italian_number("Perdita da lavoro autonomo - Ammontare")   AS _perdita_da_lavoro_autonomo_eur,
        normalize_italian_integer("Perdita da lavoro autonomo con continuita' - Frequenza")  AS perdita_da_lavoro_autonomo_con_continuita_frequenza,
        normalize_italian_number("Perdita da lavoro autonomo con continuita' - Ammontare")   AS _perdita_da_lavoro_autonomo_con_continuita_eur,
        normalize_italian_integer("Perdita da partecipazione - Frequenza")  AS perdita_da_partecipazione_frequenza,
        normalize_italian_number("Perdita da partecipazione - Ammontare")   AS _perdita_da_partecipazione_eur,
        normalize_italian_integer("Perdita di impresa in contabilita' ordinaria - Frequenza")  AS perdita_di_impresa_in_contabilita_ordinaria_frequenza,
        normalize_italian_number("Perdita di impresa in contabilita' ordinaria - Ammontare")   AS _perdita_di_impresa_in_contabilita_ordinaria_eur,
        normalize_italian_integer("Perdita di impresa in contabilita' ordinaria con continuita' - Frequenza")  AS perdita_di_impresa_in_contabilita_ordinaria_con_continuita_frequenza,
        normalize_italian_number("Perdita di impresa in contabilita' ordinaria con continuita' - Ammontare")   AS _perdita_di_impresa_in_contabilita_ordinaria_con_continuita_eur,
        normalize_italian_integer("Perdita di impresa in contabilita' semplificata - Frequenza")  AS perdita_di_impresa_in_contabilita_semplificata_frequenza,
        normalize_italian_number("Perdita di impresa in contabilita' semplificata - Ammontare")   AS _perdita_di_impresa_in_contabilita_semplificata_eur,
        normalize_italian_integer("Perdita di impresa in contabilita' semplificata con continuita' - Frequenza")  AS perdita_di_impresa_in_contabilita_semplificata_con_continuita_frequenza,
        normalize_italian_number("Perdita di impresa in contabilita' semplificata con continuita' - Ammontare")   AS _perdita_di_impresa_in_contabilita_semplificata_con_continuita_eur,
        normalize_italian_integer("Plusvalenze di natura finanziaria - Frequenza")  AS plusvalenze_di_natura_finanziaria_frequenza,
        normalize_italian_number("Plusvalenze di natura finanziaria - Ammontare")   AS _plusvalenze_di_natura_finanziaria_eur,
        normalize_italian_integer("Redditi diversi - Frequenza")  AS redditi_diversi_frequenza,
        normalize_italian_number("Redditi diversi - Ammontare")   AS _redditi_diversi_eur,
        normalize_italian_integer("Reddito agricolo dichiarato - Frequenza")  AS reddito_agricolo_dichiarato_frequenza,
        normalize_italian_number("Reddito agricolo dichiarato - Ammontare")   AS _reddito_agricolo_dichiarato_eur,
        normalize_italian_integer("Reddito complessivo - Frequenza")  AS reddito_complessivo_frequenza,
        normalize_italian_number("Reddito complessivo - Ammontare")   AS _reddito_complessivo_eur,
        normalize_italian_integer("Reddito complessivo al netto della cedolare secca - Frequenza")  AS reddito_complessivo_al_netto_della_cedolare_secca_frequenza,
        normalize_italian_number("Reddito complessivo al netto della cedolare secca - Ammontare")   AS _reddito_complessivo_al_netto_della_cedolare_secca_eur,
        normalize_italian_integer("Reddito d'impresa dichiarato - Frequenza")  AS reddito_d_impresa_dichiarato_frequenza,
        normalize_italian_number("Reddito d'impresa dichiarato - Ammontare")   AS _reddito_d_impresa_dichiarato_eur,
        normalize_italian_integer("Reddito da allevamento e produzione di vegetali - Frequenza")  AS reddito_da_allevamento_e_produzione_di_vegetali_frequenza,
        normalize_italian_number("Reddito da allevamento e produzione di vegetali - Ammontare")   AS _reddito_da_allevamento_e_produzione_di_vegetali_eur,
        normalize_italian_integer("Reddito da fabbricati - Frequenza")  AS reddito_da_fabbricati_frequenza,
        normalize_italian_number("Reddito da fabbricati - Ammontare")   AS _reddito_da_fabbricati_eur,
        normalize_italian_integer("Reddito da lavoro autonomo con continuita'* - Frequenza")  AS reddito_da_lavoro_autonomo_con_continuita_frequenza,
        normalize_italian_number("Reddito da lavoro autonomo con continuita'* - Ammontare")   AS _reddito_da_lavoro_autonomo_con_continuita_eur,
        normalize_italian_integer("Reddito da lavoro autonomo* - Frequenza")  AS reddito_da_lavoro_autonomo_frequenza,
        normalize_italian_number("Reddito da lavoro autonomo* - Ammontare")   AS _reddito_da_lavoro_autonomo_eur,
        normalize_italian_integer("Reddito da partecipazione* - Frequenza")  AS reddito_da_partecipazione_frequenza,
        normalize_italian_number("Reddito da partecipazione* - Ammontare")   AS _reddito_da_partecipazione_eur,
        normalize_italian_integer("Reddito dei terreni - Frequenza")  AS reddito_dei_terreni_frequenza,
        normalize_italian_number("Reddito dei terreni - Ammontare")   AS _reddito_dei_terreni_eur,
        normalize_italian_integer("Reddito di capitale (sez. IA e IB) - Frequenza")  AS reddito_di_capitale_sez_ia_e_ib_frequenza,
        normalize_italian_number("Reddito di capitale (sez. IA e IB) - Ammontare")   AS _reddito_di_capitale_sez_ia_e_ib_eur,
        normalize_italian_integer("Reddito di impresa in contabilita' ordinaria con continuita'* - Frequenza")  AS reddito_di_impresa_in_contabilita_ordinaria_con_continuita_frequenza,
        normalize_italian_number("Reddito di impresa in contabilita' ordinaria con continuita'* - Ammontare")   AS _reddito_di_impresa_in_contabilita_ordinaria_con_continuita_eur,
        normalize_italian_integer("Reddito di impresa in contabilita' ordinaria* - Frequenza")  AS reddito_di_impresa_in_contabilita_ordinaria_frequenza,
        normalize_italian_number("Reddito di impresa in contabilita' ordinaria* - Ammontare")   AS _reddito_di_impresa_in_contabilita_ordinaria_eur,
        normalize_italian_integer("Reddito di impresa in contabilita' semplificata con continuita'* - Frequenza")  AS reddito_di_impresa_in_contabilita_semplificata_con_continuita_frequenza,
        normalize_italian_number("Reddito di impresa in contabilita' semplificata con continuita'* - Ammontare")   AS _reddito_di_impresa_in_contabilita_semplificata_con_continuita_eur,
        normalize_italian_integer("Reddito di impresa in contabilita' semplificata* - Frequenza")  AS reddito_di_impresa_in_contabilita_semplificata_frequenza,
        normalize_italian_number("Reddito di impresa in contabilita' semplificata* - Ammontare")   AS _reddito_di_impresa_in_contabilita_semplificata_eur,
        normalize_italian_integer("Reddito di lavoro dipendente e assimilati - Frequenza")  AS reddito_di_lavoro_dipendente_e_assimilati_frequenza,
        normalize_italian_number("Reddito di lavoro dipendente e assimilati - Ammontare")   AS _reddito_di_lavoro_dipendente_e_assimilati_eur,
        normalize_italian_integer("Reddito di spettanza dell'imprenditore in contabilita' ordinaria con continuita'* - Frequenza")  AS reddito_di_spettanza_dell_imprenditore_in_contabilita_ordinaria_con_continuita_frequenza,
        normalize_italian_number("Reddito di spettanza dell'imprenditore in contabilita' ordinaria con continuita'* - Ammontare")   AS _reddito_di_spettanza_dell_imprenditore_in_contabilita_ordinaria_con_continuita_eur,
        normalize_italian_integer("Reddito di spettanza dell'imprenditore in contabilita' ordinaria* - Frequenza")  AS reddito_di_spettanza_dell_imprenditore_in_contabilita_ordinaria_frequenza,
        normalize_italian_number("Reddito di spettanza dell'imprenditore in contabilita' ordinaria* - Ammontare")   AS _reddito_di_spettanza_dell_imprenditore_in_contabilita_ordinaria_eur,
        normalize_italian_integer("Reddito di spettanza dell'imprenditore in contabilita' semplificata con continuita'* - Frequenza")  AS reddito_di_spettanza_dell_imprenditore_in_contabilita_semplificata_con_continuita_frequenza,
        normalize_italian_number("Reddito di spettanza dell'imprenditore in contabilita' semplificata con continuita'* - Ammontare")   AS _reddito_di_spettanza_dell_imprenditore_in_contabilita_semplificata_con_continuita_eur,
        normalize_italian_integer("Reddito di spettanza dell'imprenditore in contabilita' semplificata* - Frequenza")  AS reddito_di_spettanza_dell_imprenditore_in_contabilita_semplificata_frequenza,
        normalize_italian_number("Reddito di spettanza dell'imprenditore in contabilita' semplificata* - Ammontare")   AS _reddito_di_spettanza_dell_imprenditore_in_contabilita_semplificata_eur,
        normalize_italian_integer("Reddito imponibile - Frequenza")  AS reddito_imponibile_frequenza,
        normalize_italian_number("Reddito imponibile - Ammontare")   AS _reddito_imponibile_eur,
        normalize_italian_integer("Reddito imponibile addizionale - Frequenza")  AS reddito_imponibile_addizionale_frequenza,
        normalize_italian_number("Reddito imponibile addizionale - Ammontare")   AS _reddito_imponibile_addizionale_eur,
        normalize_italian_integer("Reddito netto (regime di vantaggio) - Frequenza")  AS reddito_netto_regime_di_vantaggio_frequenza,
        normalize_italian_number("Reddito netto (regime di vantaggio) - Ammontare")   AS _reddito_netto_regime_di_vantaggio_eur,
        normalize_italian_integer("Reddito netto (regime forfetario) - Frequenza")  AS reddito_netto_regime_forfetario_frequenza,
        normalize_italian_number("Reddito netto (regime forfetario) - Ammontare")   AS _reddito_netto_regime_forfetario_eur,
        normalize_italian_integer("Reddito professionale dichiarato - Frequenza")  AS reddito_professionale_dichiarato_frequenza,
        normalize_italian_number("Reddito professionale dichiarato - Ammontare")   AS _reddito_professionale_dichiarato_eur,
        normalize_italian_integer("Tassazione separata con opzione tassazione ordinaria - Frequenza")  AS tassazione_separata_con_opzione_tassazione_ordinaria_frequenza,
        normalize_italian_number("Tassazione separata con opzione tassazione ordinaria - Ammontare")   AS _tassazione_separata_con_opzione_tassazione_ordinaria_eur,
        normalize_italian_integer("Volume d'affari - Frequenza")  AS volume_d_affari_frequenza,
        normalize_italian_number("Volume d'affari - Ammontare")   AS _volume_d_affari_eur
    FROM raw_input
    WHERE normalize_string("Codice") IS NOT NULL
      AND normalize_string("Codice") NOT IN ('Codice', '0', '00')
)
SELECT
    anno,
    regione,
    cod_regione,
    numero_titolari,
    acconti_versati_frequenza, ROUND(_acconti_versati_eur * 1000, 0) AS acconti_versati_eur,
    addizionale_comunale_dovuta_frequenza, ROUND(_addizionale_comunale_dovuta_eur * 1000, 0) AS addizionale_comunale_dovuta_eur,
    addizionale_regionale_dovuta_frequenza, ROUND(_addizionale_regionale_dovuta_eur * 1000, 0) AS addizionale_regionale_dovuta_eur,
    altri_redditi_da_lavoro_autonomo_e_redditi_da_recupero_start_up_frequenza, ROUND(_altri_redditi_da_lavoro_autonomo_e_redditi_da_recupero_start_up_eur * 1000, 0) AS altri_redditi_da_lavoro_autonomo_e_redditi_da_recupero_start_up_eur,
    eccedenza_d_imposta_risultante_dalla_precedente_dichiarazione_frequenza, ROUND(_eccedenza_d_imposta_risultante_dalla_precedente_dichiarazione_eur * 1000, 0) AS eccedenza_d_imposta_risultante_dalla_precedente_dichiarazione_eur,
    imposta_lorda_frequenza, ROUND(_imposta_lorda_eur * 1000, 0) AS imposta_lorda_eur,
    imposta_netta_frequenza, ROUND(_imposta_netta_eur * 1000, 0) AS imposta_netta_eur,
    irpef_a_credito_frequenza, ROUND(_irpef_a_credito_eur * 1000, 0) AS irpef_a_credito_eur,
    irpef_a_debito_frequenza, ROUND(_irpef_a_debito_eur * 1000, 0) AS irpef_a_debito_eur,
    iva_a_debito_frequenza, ROUND(_iva_a_debito_eur * 1000, 0) AS iva_a_debito_eur,
    iva_detraibile_frequenza, ROUND(_iva_detraibile_eur * 1000, 0) AS iva_detraibile_eur,
    perdita_da_lavoro_autonomo_frequenza, ROUND(_perdita_da_lavoro_autonomo_eur * 1000, 0) AS perdita_da_lavoro_autonomo_eur,
    perdita_da_lavoro_autonomo_con_continuita_frequenza, ROUND(_perdita_da_lavoro_autonomo_con_continuita_eur * 1000, 0) AS perdita_da_lavoro_autonomo_con_continuita_eur,
    perdita_da_partecipazione_frequenza, ROUND(_perdita_da_partecipazione_eur * 1000, 0) AS perdita_da_partecipazione_eur,
    perdita_di_impresa_in_contabilita_ordinaria_frequenza, ROUND(_perdita_di_impresa_in_contabilita_ordinaria_eur * 1000, 0) AS perdita_di_impresa_in_contabilita_ordinaria_eur,
    perdita_di_impresa_in_contabilita_ordinaria_con_continuita_frequenza, ROUND(_perdita_di_impresa_in_contabilita_ordinaria_con_continuita_eur * 1000, 0) AS perdita_di_impresa_in_contabilita_ordinaria_con_continuita_eur,
    perdita_di_impresa_in_contabilita_semplificata_frequenza, ROUND(_perdita_di_impresa_in_contabilita_semplificata_eur * 1000, 0) AS perdita_di_impresa_in_contabilita_semplificata_eur,
    perdita_di_impresa_in_contabilita_semplificata_con_continuita_frequenza, ROUND(_perdita_di_impresa_in_contabilita_semplificata_con_continuita_eur * 1000, 0) AS perdita_di_impresa_in_contabilita_semplificata_con_continuita_eur,
    plusvalenze_di_natura_finanziaria_frequenza, ROUND(_plusvalenze_di_natura_finanziaria_eur * 1000, 0) AS plusvalenze_di_natura_finanziaria_eur,
    redditi_diversi_frequenza, ROUND(_redditi_diversi_eur * 1000, 0) AS redditi_diversi_eur,
    reddito_agricolo_dichiarato_frequenza, ROUND(_reddito_agricolo_dichiarato_eur * 1000, 0) AS reddito_agricolo_dichiarato_eur,
    reddito_complessivo_frequenza, ROUND(_reddito_complessivo_eur * 1000, 0) AS reddito_complessivo_eur,
    reddito_complessivo_al_netto_della_cedolare_secca_frequenza, ROUND(_reddito_complessivo_al_netto_della_cedolare_secca_eur * 1000, 0) AS reddito_complessivo_al_netto_della_cedolare_secca_eur,
    reddito_d_impresa_dichiarato_frequenza, ROUND(_reddito_d_impresa_dichiarato_eur * 1000, 0) AS reddito_d_impresa_dichiarato_eur,
    reddito_da_allevamento_e_produzione_di_vegetali_frequenza, ROUND(_reddito_da_allevamento_e_produzione_di_vegetali_eur * 1000, 0) AS reddito_da_allevamento_e_produzione_di_vegetali_eur,
    reddito_da_fabbricati_frequenza, ROUND(_reddito_da_fabbricati_eur * 1000, 0) AS reddito_da_fabbricati_eur,
    reddito_da_lavoro_autonomo_con_continuita_frequenza, ROUND(_reddito_da_lavoro_autonomo_con_continuita_eur * 1000, 0) AS reddito_da_lavoro_autonomo_con_continuita_eur,
    reddito_da_lavoro_autonomo_frequenza, ROUND(_reddito_da_lavoro_autonomo_eur * 1000, 0) AS reddito_da_lavoro_autonomo_eur,
    reddito_da_partecipazione_frequenza, ROUND(_reddito_da_partecipazione_eur * 1000, 0) AS reddito_da_partecipazione_eur,
    reddito_dei_terreni_frequenza, ROUND(_reddito_dei_terreni_eur * 1000, 0) AS reddito_dei_terreni_eur,
    reddito_di_capitale_sez_ia_e_ib_frequenza, ROUND(_reddito_di_capitale_sez_ia_e_ib_eur * 1000, 0) AS reddito_di_capitale_sez_ia_e_ib_eur,
    reddito_di_impresa_in_contabilita_ordinaria_con_continuita_frequenza, ROUND(_reddito_di_impresa_in_contabilita_ordinaria_con_continuita_eur * 1000, 0) AS reddito_di_impresa_in_contabilita_ordinaria_con_continuita_eur,
    reddito_di_impresa_in_contabilita_ordinaria_frequenza, ROUND(_reddito_di_impresa_in_contabilita_ordinaria_eur * 1000, 0) AS reddito_di_impresa_in_contabilita_ordinaria_eur,
    reddito_di_impresa_in_contabilita_semplificata_con_continuita_frequenza, ROUND(_reddito_di_impresa_in_contabilita_semplificata_con_continuita_eur * 1000, 0) AS reddito_di_impresa_in_contabilita_semplificata_con_continuita_eur,
    reddito_di_impresa_in_contabilita_semplificata_frequenza, ROUND(_reddito_di_impresa_in_contabilita_semplificata_eur * 1000, 0) AS reddito_di_impresa_in_contabilita_semplificata_eur,
    reddito_di_lavoro_dipendente_e_assimilati_frequenza, ROUND(_reddito_di_lavoro_dipendente_e_assimilati_eur * 1000, 0) AS reddito_di_lavoro_dipendente_e_assimilati_eur,
    reddito_di_spettanza_dell_imprenditore_in_contabilita_ordinaria_con_continuita_frequenza, ROUND(_reddito_di_spettanza_dell_imprenditore_in_contabilita_ordinaria_con_continuita_eur * 1000, 0) AS reddito_di_spettanza_dell_imprenditore_in_contabilita_ordinaria_con_continuita_eur,
    reddito_di_spettanza_dell_imprenditore_in_contabilita_ordinaria_frequenza, ROUND(_reddito_di_spettanza_dell_imprenditore_in_contabilita_ordinaria_eur * 1000, 0) AS reddito_di_spettanza_dell_imprenditore_in_contabilita_ordinaria_eur,
