    reddito_di_spettanza_dell_imprenditore_in_contabilita_semplificata_frequenza, ROUND(_reddito_di_spettanza_dell_imprenditore_in_contabilita_semplificata_eur * 1000, 0) AS reddito_di_spettanza_dell_imprenditore_in_contabilita_semplificata_eur,
    reddito_imponibile_frequenza, ROUND(_reddito_imponibile_eur * 1000, 0) AS reddito_imponibile_eur,
    reddito_imponibile_addizionale_frequenza, ROUND(_reddito_imponibile_addizionale_eur * 1000, 0) AS reddito_imponibile_addizionale_eur,
    reddito_netto_regime_di_vantaggio_frequenza, ROUND(_reddito_netto_regime_di_vantaggio_eur * 1000, 0) AS reddito_netto_regime_di_vantaggio_eur,
    reddito_netto_regime_forfetario_frequenza, ROUND(_reddito_netto_regime_forfetario_eur * 1000, 0) AS reddito_netto_regime_forfetario_eur,
    reddito_professionale_dichiarato_frequenza, ROUND(_reddito_professionale_dichiarato_eur * 1000, 0) AS reddito_professionale_dichiarato_eur,
    tassazione_separata_con_opzione_tassazione_ordinaria_frequenza, ROUND(_tassazione_separata_con_opzione_tassazione_ordinaria_eur * 1000, 0) AS tassazione_separata_con_opzione_tassazione_ordinaria_eur,
    volume_d_affari_frequenza, ROUND(_volume_d_affari_eur * 1000, 0) AS volume_d_affari_eur
